package com.bplus.share;
import android.app.*;import android.os.*;import android.widget.*;import org.json.*;
public final class TransfersActivity extends Activity{private LinearLayout rows;private final Handler h=new Handler();private boolean active;private final Runnable tick=new Runnable(){public void run(){if(!active)return;render();h.postDelayed(this,1000);}};public void onCreate(Bundle b){super.onCreate(b);Ui.applyLocale(this);Ui.applyTheme(this);LinearLayout root=Ui.col(this);root.setBackgroundColor(Ui.bg);root.addView(Ui.topBar(this,getString(R.string.file_transfers),true,null));ScrollView sc=new ScrollView(this);rows=Ui.col(this);Ui.pad(rows,20,10,20,20,this);sc.addView(rows);root.addView(sc,Ui.lpW1());setContentView(root);}protected void onResume(){super.onResume();active=true;h.post(tick);}protected void onPause(){active=false;h.removeCallbacksAndMessages(null);super.onPause();}private void render(){rows.removeAllViews();JSONArray peers=Store.listedPeers();for(int i=0;i<peers.length();i++){JSONObject peer=peers.optJSONObject(i);if(peer==null)continue;String id=peer.optString("id");JSONArray history=Store.thread(id);for(int n=history.length()-1;n>=0;n--){JSONObject m=FileJobs.display(history.optJSONObject(n));if(m==null||!m.optBoolean("me")||m.optString("job").isEmpty())continue;LinearLayout card=Ui.col(this);Ui.pad(card,16,12,16,16,this);card.setBackground(Ui.roundBorder(Ui.card,Ui.border,16,this));card.addView(Ui.t(this,m.optString("name")+" → "+peer.optString("name"),15,Ui.text,App.cairoB));card.addView(Ui.t(this,phaseLabel(m.optString("phase"))+" · "+(m.optLong("done")*100/Math.max(1,m.optLong("size")))+"% · "+Ui.fmtSize(m.optLong("speed"))+"/s",12,Ui.dim,App.cairoSB));if(FileJobs.active(m.optString("job"))){TextView stop=Ui.ghost(this,getString(R.string.cancel));card.addView(stop);stop.setOnClickListener(v->FileJobs.cancel(m.optString("job")));}else if(!m.optString("state").equals("sent")){TextView retry=Ui.ghost(this,getString(R.string.retry_file));card.addView(retry);retry.setOnClickListener(v->new Thread(()->FileJobs.retry(id,m)).start());}if(m.has("timing")){TextView copy=Ui.ghost(this,getString(R.string.copy_details));card.addView(copy);copy.setOnClickListener(v->PairUi.copy(this,m.optJSONObject("timing").toString()));}LinearLayout.LayoutParams lp=Ui.lp(-1,-2);lp.bottomMargin=Ui.dp(this,12);rows.addView(card,lp);}}}private String phaseLabel(String phase){return getString(phase.equals("cancelling")?R.string.file_cancelling:phase.equals("connecting")?R.string.file_connecting:phase.equals("confirming")?R.string.file_confirming:phase.equals("retrying")?R.string.file_retrying:phase.equals("sent")?R.string.sent:phase.equals("failed")?R.string.file_failed_actions:phase.equals("cancelled")?R.string.status_canceled:R.string.sending);}}
